				if(random == 0){
					this.type = 4;
					this.shape.x = -this.shape.width;
				}
				else if(random == 1){
					this.type = 0;
					this.shape.x = gameWidth;
				}
				var filters = this.shape.filters;
				filters.push(glowFilter);
				this.shape.filters = filters;
				this.shape.y = Utils.rand(0, gameHeight - this.shape.height);
				this.vx = 2;
				this.shape.textColor = 0x006666;
				break;
			case 13:
				this.vR = Utils.rand(-5, 5);
				this.shape.rotationZ = Utils.rand(-180, 180);
				this.shape.x = Utils.rand(0, gameWidth);
				this.shape.y = gameHeight;
				this.vx = (this.shape.x < gameWidth / 2) ? Utils.rand(0, 10) : Utils.rand(-10, 0);
				this.vy = Utils.rand(-gameHeight / 12, -gameHeight / 30);
				this.shape.textColor = Utils.rgb(Utils.rand(0x00, 0x55),Utils.rand(0x00, 0x55),Utils.rand(0x00, 0x55));
				this.leaveType = 4;
				break;
			case 14:
				var random = Utils.rand(0,2);
				if(random == 0){
					this.shape.x = 0;
					this.shape.y = Utils.rand(0, gameHeight / 2);
				}
				else{
					this.shape.x = Utils.rand(0, gameWidth / 2);
					this.shape.y = 0;
				}
				this.shape.rotationZ = 222;
				this.shape.textColor = Utils.rgb(Utils.rand(0x00, 0x55),Utils.rand(0x00, 0x55),Utils.rand(0x00, 0x55));
				this.vx = 5.2;
				this.vy = 4.684;
				this.leaveType = 5;
				break;
			case 15:
				var random = Utils.rand(0,2);
				if(random == 0){
					this.shape.x = 0;
					this.shape.y = Utils.rand(0, gameHeight / 2);
				}
				else{
					this.shape.x = Utils.rand(0, gameWidth / 2);
					this.shape.y = 0;
				}
				this.shape.rotationZ = 222;
				this.shape.textColor = Utils.rgb(Utils.rand(0x00, 0x55),Utils.rand(0x00, 0x55),Utils.rand(0x00, 0x55));
				this.shape.scaleX = Math.random() * 1.5 + 0.5;
				this.shape.scaleY = Math.random() * 1.5 + 0.5;
				this.vx = 5.2;
				this.vy = 4.684;
				this.leaveType = 5;
				break;
			case 16:
				this.shape.x = gameWidth;
				this.shape.y = Utils.rand(0, gameHeight - this.shape.height);
				this.shape.rotationY = Utils.rand(-45,45);
				this.vx = Utils.rand(3,7);
				this.shape.textColor = Utils.rand(0x000000, 0xffffff);
				this.leaveType = 0;
				break;
		}
	};

	danmu.move = function()
	{
		switch(this.type)
		{
			case 0:
				this.shape.x -= this.vx;
				break;
			case 1:
				this.shape.x -= this.vx;
				break;
			case 2:
				this.shape.x -= this.vx;
				this.shape.y -= this.vy;
				break;
			case 3:
				break;
			case 4:
				this.shape.x += this.vx;
				break;
			case 5:
				this.shape.x -= this.vx;
				this.scale = Math.sin(timeline/2.27) / 2 + 1;
				this.shape.scaleX = this.scale;
				this.shape.scaleY = this.scale;
				break;
			case 6:
				this.shape.x -= this.vx;
				this.scale = Math.sin(timeline) / 2 + 1;
				this.shape.scaleX = this.scale;
				this.shape.scaleY = this.scale;
				break;
			case 7:
				this.shape.y += this.vy;
				break;
			case 8:
				this.vy += this.ay;
				this.shape.y += this.vy;
				break;
			case 9:
				this.shape.x -= this.vx;
				this.shape.y -= this.vy;
				break;
			case 10:
				this.shape.x += this.vx;
				this.shape.y += this.vy;
				break;
			case 11:
				if(this.shape.x >= gameWidth - this.shape.width)
					this.shape.x -= this.vx;
				else{
					var reference = (Math.atan2(this.shape.y - player.shape.y, this.shape.x - player.shape.x)) / pai_180;
					if(this.rotation > reference)
						this.rotation = this.rotation - 1;
					else if(this.rotation < reference)
						this.rotation = this.rotation + 1;
					this.shape.rotationZ = this.rotation;
					this.vx = this.v * Math.cos(this.rotation * pai_180);
					this.vy = this.v * Math.sin(this.rotation * pai_180);
					this.shape.x -= this.vx;
					this.shape.y -= this.vy;
				}
				break;
			case 12:
				break;
			case 13:
				this.shape.rotationZ += this.vR;
				this.vy += 1;
				this.shape.x += this.vx;
				this.shape.y += this.vy;
				break;
			case 14:
				this.shape.x += this.vx;
				this.shape.y += this.vy;
				break;
			case 15:
				this.shape.x += this.vx;
				this.shape.y += this.vy;
				break;
			case 16:
				this.shape.x -= this.vx;
				break;
		}
	};

	danmu.checkLeave = function()
	{
		switch(this.leaveType)
		{
			case 0: //出左边界即离开
				if(this.shape.x < -this.shape.width)
				{
					$.root.removeChild(this.shape);
					return true;
				}
				else
					return false;
				break;
			case 1: //适用倾斜弹幕，检测上下左右四个方向
				if(this.shape.x < -this.shape.width || this.shape.x > gameWidth + this.shape.width || this.shape.y < -this.shape.height || this.shape.y > gameHeight + this.shape.height)
				{
					$.root.removeChild(this.shape);
					return true;
				}
				else
					return false;
				break;
			case 2: //出右边界即离开
				if(this.shape.x > gameWidth)
				{
					$.root.removeChild(this.shape);
					return true;
				}
				else
					return false;
				break;
			case 3: //出下边界即离开
				if(this.shape.y > gameHeight)
				{
					$.root.removeChild(this.shape);
					return true;
				}
				else
					return false;
				break;
			case 4: //用于弹跳弹幕
				if(this.shape.y > gameHeight + 10)
				{
					$.root.removeChild(this.shape);
					return true;
				}
				else
					return false;
				break;
			case 5: //左上角至右下角弹幕
				if(this.shape.x > gameWidth + this.shape.width || this.shape.y > gameHeight + this.shape.height)
				{
					$.root.removeChild(this.shape);
					return true;
				}
				else
					return false;
				break;
			case 6: //完全透明则消失
				if(this.shape.alpha <= 0)
				{
					$.root.removeChild(this.shape);
					return true;
				}
				else
					return false;
				break;
		}
	};

	return danmu;
}

function createPlayer()
{
	var player = {};
	$G._set("player",player);
	var shapes = [6];
	var bmd = loadBitmapData(playerWidth * 6, playerHeight, RAW_player);

	for (var i = 0; i < 6; i++) 
	{
		var tempBmd = Bitmap.createBitmapData(playerWidth, playerHeight, true);
		var point = $.createPoint(0, 0);
		var rect = Bitmap.createRectangle(playerWidth * i, 0, playerWidth, playerHeight);
		tempBmd.copyPixels(bmd, rect, point);
		shapes[i] = Bitmap.createBitmap({bitmapData:tempBmd, lifeTime:0});
		shapes[i].x = -playerWidth / 2;
		shapes[i].y = -playerHeight / 2;
		shapes[i].remove();		
	}

	player.normal = shapes[0];
	player.forwards = shapes[1];
	player.backwards = shapes[2];
	player.upwards = shapes[3];
	player.downwards = shapes[4];
	player.fall = shapes[5];

	player.shape = $.createCanvas({lifeTime:0, x:0, y:0});
	playerShape = player.shape;
	playerShape.addChild(player.normal);

	player.shield = $.createShape({x:0, y:0, lifeTime:0});
	player.shield.graphics.lineStyle(3, 0x00ffff);
	player.shield.graphics.drawCircle(player.shape.width >> 1, player.shape.height >> 1, 55 );
	player.shield.remove();

	player.speed = 10;
	player.fallSpeed = 0;
	player.bornSpeed = 5;
	player.state = 0; //0：静止，1：上，2：下，3：左，4：右 

	player.keyDown = [];
	player.keyDown[Keyboard.W] = 0;
	player.keyDown[Keyboard.S] = 0;
	player.keyDown[Keyboard.A] = 0;
	player.keyDown[Keyboard.D] = 0;
	Player.keyTrigger(function(keyCode){
		player.keyDown[keyCode] = true;
		}, MAX_NUM);
	Player.keyTrigger(function(keyCode) {
		player.keyDown[keyCode] = false;
		}, MAX_NUM, true);

	return player;
}

function createBackground()
{
	background = $.createShape({x:0,y:0,lifeTime:0});
	background.graphics.beginFill(0x000000);
	background.graphics.drawRect(0,0,Player.width,Player.height);
	background.graphics.endFill();
	$.root.setChildIndex(background, 0);
}

function movePlayer()
{
	if(!alive)
		return;
	if (player.keyDown[Keyboard.W ^ 0]) 
	{
		newY = playerShape.y - player.speed;
		if(newY < playerHeight >> 1)
			playerShape.y = playerHeight >> 1;
		else
			playerShape.y = newY;
		player.state = 1;
	}
	else if (player.keyDown[Keyboard.S ^ 0]) 
	{
		newY = playerShape.y + player.speed;
		if(newY > gameHeight - (playerHeight >> 1))
			playerShape.y = gameHeight - (playerHeight >> 1);
		else
			playerShape.y = newY;
		player.state = 2;
	}
	if (player.keyDown[Keyboard.A ^ 0])
	{
		newX = playerShape.x - player.speed;
		if(newX < playerWidth >> 1)
			playerShape.x = playerWidth >> 1;
		else
			playerShape.x = newX;
		player.state = 3;
	}
	else if (player.keyDown[Keyboard.D ^ 0]) 
	{
		newX = playerShape.x + player.speed;
		if(newX > gameWidth - (playerWidth >> 1))
			playerShape.x = gameWidth - (playerWidth >> 1);
		else
			playerShape.x = newX;
		player.state = 4;
	}
	if(player.keyDown[65] + player.keyDown[83] + player.keyDown[87] + player.keyDown[68] == 0)
		player.state = 0;

	if(player.state != player.oldState)
	{
		playerShape.removeChildAt(0);
		switch(player.state)
		{
			case 0:
				playerShape.addChild(player.normal);
				break;
			case 1:
				playerShape.addChild(player.upwards);
				break;
			case 2:
				playerShape.addChild(player.downwards);
				break;
			case 3:
				playerShape.addChild(player.backwards);
				break;
			case 4:
				playerShape.addChild(player.forwards);
				break;
		}
		player.oldState = player.state;
	}

	if(indestructible)
	{
		player.shield.x = playerShape.x - playerWidth / 2;
		player.shield.y = playerShape.y - playerHeight / 2;
	}
}

function hitTest(objectA, objectB)
{
	if(objectA.x + objectA.width >= objectB.x && objectA.x <= objectB.x + objectB.width && objectA.y + objectA.height >= objectB.y && objectA.y <= objectB.y + objectB.height)
		return true;
	else
		return false;
}

function hitPoint(object, x, y)
{
	oX = object.x;
	oY = object.y;
	pX = x;
	pY = y;
	rotation = object.rotationZ * pai_180;
	if(rotation != 0)
	{
		oX = object.x * Math.cos(rotation) + object.y * Math.sin(rotation);
		oY = -object.x * Math.sin(rotation) + object.y * Math.cos(rotation);
		pX = x * Math.cos(rotation) + y * Math.sin(rotation);
		pY = -x * Math.sin(rotation) + y * Math.cos(rotation);
	}
	if(pX >= oX && pX <= oX + object.width && pY >= oY && pY <= oY + object.height)
		return true;
	else
		return false;
}

function born()
{
	playerShape.removeChildAt(0);
	playerShape.addChild(player.normal);
	playerShape.y = Player.height / 2;
	playerShape.x = -playerShape.width >> 2;
	indestructible = true;

	$.root.addChild(player.shield);
	player.shield.x = playerShape.x - playerWidth / 2;
	player.shield.y = playerShape.y - playerHeight / 2;

	$.root.addEventListener("enterFrame",bornAnime);
	timer(function(){
		indestructible = false;
		player.shield.remove();
	},3000);
}

function die()
{
	alive = false;
	deadTime++;
	scoreboard.text = "死亡次数：" + deadTime;
	playerShape.removeChildAt(0);
	playerShape.addChild(player.fall);
	$.root.addEventListener("enterFrame",dieAnime);
}

function bornAnime()
{
	if(Player.state != "playing")
		return;
	playerShape.x += player.bornSpeed;
	player.shield.x = playerShape.x - playerWidth / 2;
	if(playerShape.x >= 60)
	{
		$.root.removeEventListener("enterFrame",bornAnime);
		alive = true;
	}
}

function dieAnime()
{
	if(Player.state != "playing")
		return;
	player.fallSpeed += GRAVITY;
	playerShape.y += player.fallSpeed;
	if(playerShape.y > gameHeight + 50)
	{
		$.root.removeEventListener("enterFrame",dieAnime);
		player.fallSpeed = 0;
		born();
	}
}

