//弹幕与自机的碰撞检测
function checkCollision()
{
	if(indestructible)
	{
		for(var i = danmus.length-1; i >= 0; i--)
		{
			current = danmus[i].shape;

			if((player.shield).hitTestObject(current))
			{
				($.root).removeChild(current);
				danmus[i] = null;
				danmus.splice(i, 1);
			}
		}
	}
	else
	{
		for(var i = danmus.length-1; i >= 0; i--)
		{
			current = danmus[i].shape;

			if(alive)
			{
				if(hitPoint(current, playerShape.x, playerShape.y))
				{
					die();
					break;
				}
			}
		}
	}
}

//移动弹幕，离开场景时移除
function moveDanmus()
{
	for(var i = danmus.length-1; i >= 0; i--)
	{
		danmus[i].move();
		if(danmus[i].checkLeave())
		{
			danmus.splice(i, 1);
		}
	}
}

function scaleGameArea()
{
	if(gameWidth == Player.width && gameHeight == Player.height)
		return;
	gameWidth = Player.width;
	gameHeight = Player.height;

	($.root.getChildAt(0)).width = gameWidth;
	($.root.getChildAt(0)).height = gameHeight;
	// $.root.setChildIndex(background, 0);
}

function mainLoop()
{
	scaleGameArea();

	if(Player.state != "playing")
		return;

	movePlayer();
	moveDanmus();

	checkCollision();

	timeline++;

	if(Player.time >= 360000){
		$G._set("numDanmu", numDanmu);
		$G._set("deadTime", deadTime);
		scoreboard.remove();
		$.root.removeEventListener("enterFrame", mainLoop);
		$.root.removeEventListener("added", added);
	}
}

function added(e)
{
	if(e.target.selectable) //为true则为自带弹幕，克隆后删除
	{
		var cloned = clone(e.target);
		cloned.selectable = false;
		// if(format == null)
		// 	format = e.target.defaultTextFormat;
		cloned.setTextFormat(e.target.getTextFormat());
		if(filters == null)
			filters = e.target.filters;
		cloned.filters = filters;
		// cloned.filters = e.target.filters;

		$.root.removeChild(e.target);
		$.root.addChild(cloned);
		var danmu = createDanmu();
		danmu.init(cloned);
		danmus[danmus.length] = danmu;
		numDanmu++;
	}
}

function debug()
{
	Player.keyTrigger(function(keyCode){
		if(keyCode == 36)
		{
			trace(numDanmu);
		}
	}, MAX_NUM);
}

function main()
{
	init();

	$.root.addEventListener("enterFrame", mainLoop);
	$.root.addEventListener("added", added);
}

