function flash()
{
	while(true)
	{
		if(changedShape != null)
		{
			changedShape.scaleX = 1;
			changedShape.scaleY = 1;
			changedShape.x = changedShape.x + offsetX;
			changedShape.y = changedShape.y + offsetY;
		}

		random = Utils.rand(0, danmus.length);
		danmuShape = danmus[random].shape;
		if(danmus.length >= 1 && danmuShape.scaleX != 1)
			continue;
		offsetX = danmuShape.width / 2;
		offsetY = danmuShape.height / 2;
		danmuShape.x = danmuShape.x - offsetX;
		danmuShape.y = danmuShape.y - offsetY;
		danmuShape.scaleX = 2;
		danmuShape.scaleY = 2;

		changedShape = danmuShape;
		break;
	};
}

