{
	for (var i = danmus.length - 1; i >= 0; i--) {
		if(danmus[i].backRotate == null){
			danmus[i].backRotate = danmus[i].shape.rotationZ / 12;
			trace(danmus[i].shape.rotationZ);
			trace(danmus[i].backRotate);
		}
		danmus[i].shape.rotationZ -= danmus[i].backRotate;
	}
}

function addEvent()
{
	$.root.addEventListener("enterFrame", rotate);
	timer(function(){
		$.root.removeEventListener("enterFrame", rotate);
	}, 100);
}

Utils.interval(addEvent, 380, 4);

