var danmus = $G._("danmus");
var step = 0;

function move()
{
	for (var i = danmus.length - 1; i >= 0; i--) {
		if(i % 4 == step) {
			if(danmus[i].tempVy == null){
				if(danmus[i].shape.y < Player.height / 2)
					danmus[i].tempVy = 30;
				else
					danmus[i].tempVy = -30;
			}
			danmus[i].shape.y += danmus[i].tempVy;
		}
	}
}

function addEvent()
{
	$.root.addEventListener("enterFrame", move);
	timer(function(){
		$.root.removeEventListener("enterFrame", move);
		step++;
	}, 200);
}

Utils.interval(addEvent, 380, 4);

