bg = $.root.getChildAt(4);

function leave(){
	switch(step)
	{
		case 0:
			bg.x += vx;
			if(bg.x > Player.width){
				$.root.removeChild(bg);
				step++;
				bg = $.root.getChildAt(3);
			}
			break;
		case 1:
			bg.y += vy;
			if(bg.y > Player.height){
				$.root.removeChild(bg);
				step++;
				bg = $.root.getChildAt(2);
			}
			break;
		case 2:
			bg.x -= vx;
			if(bg.x < -Player.width){
				$.root.removeChild(bg);
				step++;
				bg = $.root.getChildAt(1);
			}
			break;
		case 3:
			bg.y -= vy;
			if(bg.y < -Player.height){
				$.root.removeChild(bg);
				step++;
				bg = $.root.getChildAt(0);
			}
			break;
		case 4:
			$.root.removeEventListener("enterFrame", leave);
	}
}

$.root.addEventListener("enterFrame", leave);

