var distance = 0;
var pai_180 = Math.PI / 180;

function moveToPlayer()
{
	var i = Utils.rand(0, danmus.length-1);
	current = danmus[i];
	distance = Math.sqrt((playerShape.x - current.shape.x) * (playerShape.x - current.shape.x) + (playerShape.y - current.shape.y) * (playerShape.y - current.shape.y));
	current.vx = 25 * (playerShape.x - current.shape.x) / distance;
	current.vy = 25 * (playerShape.y - current.shape.y) / distance;
	current.leaveType = 1;
}

