var danmus = $G._("danmus");
var PAI_180 = Math.PI / 180;
var nextX = 0;
var nextY = 0;

function createNewDanmu(danmu,text,index,total,format)
{
	var newDanmu = clone(danmu);
	newDanmu.shape.x = danmu.shape.x + index * 14 * Math.cos(danmu.shape.rotationZ * PAI_180);
	newDanmu.shape.y = danmu.shape.y + index * 14 * Math.sin(danmu.shape.rotationZ * PAI_180);
	newDanmu.shape.text = text;
	newDanmu.shape.setTextFormat(format);
	newDanmu.vx = 10 * (index / total - 0.5);
	newDanmu.vy = 0;
	newDanmu.ay = 1;
	newDanmu.move = function()
	{
		this.vy += this.ay;
		this.shape.x += this.vx;
		this.shape.y += this.vy;
	};

	newDanmu.checkLeave = function()
	{
		if(this.shape.y > Player.height)
		{
			$.root.removeChild(this.shape);
			return true;
		}
		else
			return false;

	};
	return newDanmu;
}

for (var i = danmus.length - 1; i >= 0; i--) {
	var text = danmus[i].shape.text;
	var char_arr = text.split('');
	var total = char_arr.length;
	var format = danmus[i].shape.getTextFormat();
	for (var j = char_arr.length - 1; j >= 0; j--) {
		var newDanmu = createNewDanmu(danmus[i],char_arr[j],j,total,format);
		danmus.push(newDanmu);
		$.root.addChild(newDanmu.shape);
	};

	danmus[i].leaveType = 0;
	danmus[i].shape.x = -10000;
}

//"everything faded away"

var danmus = $G._("danmus");
var alpha = danmus[0].shape.alpha;

function fadeAway()
{
	if(alpha >= 0){
		alpha -= 0.02;
		for (var i = danmus.length - 1; i >= 0; i--) {
			danmus[i].shape.alpha = alpha;
		};
	}
	else{
		for (var i = danmus.length - 1; i >= 0; i--) {
			danmus[i].leaveType = 0;
			danmus[i].shape.x = -10000;
		};
		$.root.removeEventListener("enterFrame", fadeAway);
	}
}

$.root.addEventListener("enterFrame", fadeAway);

