function flash () {
	if(Player.state != "playing")
		return;

	if(timeLine == 3.6 * 30)
		speed = 1.4;
	else if(timeLine == 5.4 * 30)
		speed = 0.8;
	else if(timeLine > 7.253 * 30){
		$.root.removeChild(bg);
		$.root.removeEventListener("enterFrame", flash);
	}

	bg.alpha = Math.cos(timeLine/speed);
	timeLine++;
}

