var vSy = 0;

function scaleAll() {
	for (var i = danmus.length - 1; i >= 0; i--) {
		danmus[i].shape.scaleX = danmus[i].shape.scaleX + vSx;
		danmus[i].shape.scaleY = danmus[i].shape.scaleY + vSy;
	};
}

function addEvent()
{
	$.root.addEventListener("enterFrame", scaleAll);
	timer(function(){
		$.root.removeEventListener("enterFrame", scaleAll);
		step++;
		if(step == 1){
			vSx = 0;
			vSy = Math.random();
		}
		else if(step == 2){
			vSx = -Math.random();
			vSy = 0;
		}
		else{
			vSx = 0;
			vSy = Math.random();
		}
	}, 100);
}

